    for (int i = 0; i < j["array"].size(); i++) {
        arr[i] = j["array"][i];
    }

    bubbleSort(arr, j["array"].size());

    // Output sorted array
    for (int i = 0; i < j["array"].size(); i++) {
        std::cout << arr[i] << " ";
    }

    return 0;
}
```

