```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    size_t arg_len = 0;
    char *args = NULL;

    for (int I = 0; I < argc; i++) {
        arg_len += strlen(argv[i]) + 1; // add space for null terminator
    }

    args = malloc(arg_len);
    if (!args) {
        perror("Failed to allocate memory");
        return EXIT_FAILURE;
    }

    int pos = 0;
    for (int I = 0; I < argc; i++) {
        strcpy(args + pos, argv[i]);
        pos += strlen(argv[i]) + 1;
    }

    printf("Converted string: %s\n", args);

    free(args);
    return EXIT_SUCCESS;
}
```

